NAVY, BLUE, INK, MUTED = '#123047', '#1B6CA8', '#1E2933', '#586774'
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleX', fontName='Arial-Bold', fontSize=25, leading=31, textColor=NAVY, alignment=1, spaceAfter=14))
styles.add(ParagraphStyle(name='SubX', fontName='Arial', fontSize=12, leading=17, textColor=MUTED, alignment=1, spaceAfter=22))
